using EjemploABM.Modelo; using System; using System.Collections.Generic; using System.Data.SqlClient;
namespace EjemploABM.Controladores { internal static class EmailEnvio_Controller { public static List<EmailEnvio> ObtenerTodos(){var l=new List<EmailEnvio>(); if(DB_Controller.connection==null)DB_Controller.initialize(); using(var c=new SqlConnection(DB_Controller.connection.ConnectionString)) using(var q=new SqlCommand("SELECT id,tipo,destinatario,asunto,estado,error,intentos,fecha FROM email_envio ORDER BY fecha DESC",c)){c.Open();using(var r=q.ExecuteReader()){while(r.Read())l.Add(new EmailEnvio{Id=r.GetInt32(0),Tipo=r.GetString(1),Destinatario=r.GetString(2),Asunto=r.GetString(3),Estado=r.GetString(4),Error=r.IsDBNull(5)?"":r.GetString(5),Intentos=r.GetInt32(6),Fecha=r.GetDateTime(7)});}}return l;} } }
